const payload = $json.body ?? $json;
const allowedTypes = new Set(['qualified_lead','client_support','portal_support','general_escalation']);
const routeKeys = { qualified_lead: 'CADRE_SALES_EMAIL', client_support: 'CADRE_CLIENT_SUCCESS_EMAIL', portal_support: 'CADRE_SUPPORT_EMAIL', general_escalation: 'CADRE_GENERAL_EMAIL' };
const fail = (reason) => [{ json: { ok: false, status: 'failed', reason } }];
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return fail('invalid_payload');
if (!allowedTypes.has(payload.type)) return fail('invalid_type');
if (payload.consent_to_contact !== true) return fail('consent_required');
if (payload.source !== 'cadre-ai-concierge') return fail('invalid_source');
const email = payload.contact?.email;
if (typeof email !== 'string' || email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return fail('invalid_email');
if (typeof payload.intent !== 'string' || !payload.intent.trim() || typeof payload.summary !== 'string' || !payload.summary.trim() || typeof payload.recommended_next_step !== 'string' || !payload.recommended_next_step.trim()) return fail('missing_required_field');
const clean = (value, max = 500) => typeof value === 'string' ? value.trim().slice(0, max) : '';
const pains = Array.isArray(payload.pain_points) ? payload.pain_points.filter((v) => typeof v === 'string').slice(0, 8).map((v) => clean(v, 160)) : [];
const destinationKey = routeKeys[payload.type];
const company = clean(payload.company?.name, 160);
const notification = { subject: `[Cadre AI Concierge] ${payload.type} — ${company || email}`, contact: { name: clean(payload.contact?.name, 120), email }, company: { name: company, industry: clean(payload.company?.industry, 160) }, intent: clean(payload.intent, 240), topic: clean(payload.topic, 240), pain_points: pains, volume: clean(payload.volume, 160), recommended_next_step: clean(payload.recommended_next_step, 300), summary: clean(payload.summary, 1200), source: 'cadre-ai-concierge' };
return [{ json: { ok: true, status: 'accepted', handoffId: `n8n-${$execution.id}`, route: destinationKey, notification } }];
